/**
 * Wrangler dotenv values for the Worker-hosted emulated providers.
 *
 * Shared by `scripts/dev.ts` and the Playwright configs so local dev, the web
 * suite and the mobile suite all point at the same in-Worker emulator.
 */

export const EMULATE_GITHUB_SECRET = "emulate-github-secret";
export const EMULATE_GOOGLE_SECRET = "emulate-google-secret";

export function emulateEnvFile({
	origin,
	disableRateLimit,
}: {
	origin: string;
	disableRateLimit: boolean;
}): string {
	return [
		"# Generated by scripts/dev.ts / the Playwright configs.",
		"# The emulated GitHub/Google providers are served by the Worker itself.",
		`BETTER_AUTH_URL=${origin}`,
		"EMULATE_ENABLED=true",
		`EMULATE_GOOGLE_URL=${origin}/emulate/google`,
		`EMULATE_GITHUB_URL=${origin}/emulate/github`,
		`GITHUB_CLIENT_SECRET=${EMULATE_GITHUB_SECRET}`,
		`GOOGLE_CLIENT_SECRET=${EMULATE_GOOGLE_SECRET}`,
		// No emulated mailbox: leaving the key empty makes better-auth log the
		// invitation link instead of calling Resend.
		"RESEND_API_KEY=",
		`DISABLE_RATE_LIMIT=${disableRateLimit}`,
		"",
	].join("\n");
}

/** Real providers: no emulation overrides, only the values the run needs. */
export function realProviderEnvFile({
	origin,
	disableRateLimit,
}: {
	origin: string;
	disableRateLimit: boolean;
}): string {
	return [
		"# Generated by scripts/dev.ts (EMULATE=0).",
		`BETTER_AUTH_URL=${origin}`,
		`DISABLE_RATE_LIMIT=${disableRateLimit}`,
		"",
	].join("\n");
}
